const input = $json.body ?? $json;
const errors = [];
const allowed = ['ordering_check', 'category_reintroduction', 'service_recovery'];
const isDate = (v) => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && !Number.isNaN(Date.parse(v + 'T00:00:00Z'));
if (typeof input.accountId !== 'string' || !input.accountId.trim()) errors.push({ field: 'accountId', message: 'accountId is required and must be a non-empty string' });
if (!isDate(input.analysisDate)) errors.push({ field: 'analysisDate', message: 'analysisDate is required in YYYY-MM-DD format' });
if (!allowed.includes(input.actionType)) errors.push({ field: 'actionType', message: 'Unsupported actionType', allowedValues: allowed });
if (!input.evidence || typeof input.evidence !== 'object' || Array.isArray(input.evidence)) errors.push({ field: 'evidence', message: 'evidence is required and must be an object; unavailable values may be null or omitted' });
const e = input.evidence && typeof input.evidence === 'object' && !Array.isArray(input.evidence) ? input.evidence : {};
const numeric = [['daysSinceLastOrder', 0, null], ['typicalOrderingIntervalDays', 0, null], ['spendingDeclinePercent', 0, 100], ['recentReviewScore', 0, 5], ['deliveryLatenessDays', 0, null]];
for (const [key, min, max] of numeric) {
  if (e[key] !== undefined && e[key] !== null && (typeof e[key] !== 'number' || !Number.isFinite(e[key]) || e[key] < min || (max !== null && e[key] > max))) errors.push({ field: `evidence.${key}`, message: `must be null, omitted, or a number${max === null ? ` >= ${min}` : ` from ${min} to ${max}`}` });
}
for (const key of ['droppedCategories', 'riskReasons']) {
  if (e[key] !== undefined && e[key] !== null && (!Array.isArray(e[key]) || e[key].some((v) => typeof v !== 'string' || !v.trim()))) errors.push({ field: `evidence.${key}`, message: 'must be null, omitted, or an array of non-empty strings' });
}
if (e.evidenceConfidence !== undefined && e.evidenceConfidence !== null && !['low', 'medium', 'high', 'unavailable'].includes(e.evidenceConfidence)) errors.push({ field: 'evidence.evidenceConfidence', message: 'must be low, medium, high, unavailable, null, or omitted' });
if (e.unresolvedServiceIssue !== undefined && e.unresolvedServiceIssue !== null && typeof e.unresolvedServiceIssue !== 'boolean') errors.push({ field: 'evidence.unresolvedServiceIssue', message: 'must be boolean, null, or omitted' });
if (e.reviewText !== undefined && e.reviewText !== null && typeof e.reviewText !== 'string') errors.push({ field: 'evidence.reviewText', message: 'must be string, null, or omitted' });
if (errors.length) return [{ json: { ok: false, httpCode: 400, body: { error: { code: 'INVALID_REQUEST', message: 'Prepare Action request failed validation', details: errors } } } }];
return [{ json: { ok: true, request: { ...input, accountId: input.accountId.trim(), evidence: e } } }];

if (!$json.ok) return [{ json: $json }];
const request = $json.request;
const serviceOverride = request.evidence.unresolvedServiceIssue === true;
const selectedActionType = serviceOverride ? 'service_recovery' : request.actionType;
return [{ json: { ...$json, selectedActionType, selectionReason: serviceOverride && request.actionType !== 'service_recovery' ? 'unresolved_service_issue_precedence' : 'requested_action' } }];

if (!$json.ok) return [{ json: $json }];
const { request, selectedActionType } = $json;
const e = request.evidence;
const facts = [];
const has = (key) => e[key] !== undefined && e[key] !== null;
if (has('daysSinceLastOrder')) facts.push(`It has been ${e.daysSinceLastOrder} day${e.daysSinceLastOrder === 1 ? '' : 's'} since the last order.`);
if (has('typicalOrderingIntervalDays')) facts.push(`The typical ordering interval is ${e.typicalOrderingIntervalDays} day${e.typicalOrderingIntervalDays === 1 ? '' : 's'}.`);
if (has('spendingDeclinePercent')) facts.push(`Recorded spending is down ${e.spendingDeclinePercent}% in the supplied comparison.`);
if (Array.isArray(e.droppedCategories) && e.droppedCategories.length) facts.push(`Dropped categories: ${e.droppedCategories.join(', ')}.`);
if (has('recentReviewScore')) facts.push(`The recent review score supplied is ${e.recentReviewScore} out of 5.`);
if (has('deliveryLatenessDays')) facts.push(`The supplied delivery record shows ${e.deliveryLatenessDays} day${e.deliveryLatenessDays === 1 ? '' : 's'} of lateness.`);
if (Array.isArray(e.riskReasons) && e.riskReasons.length) facts.push(`Risk reasons supplied: ${e.riskReasons.join('; ')}.`);
const confidence = has('evidenceConfidence') ? e.evidenceConfidence : 'unavailable';
const cautious = confidence === 'low' || confidence === 'unavailable';
const confidenceLine = cautious ? 'Evidence confidence is limited, so verify the situation before proposing any action.' : `Evidence confidence is ${confidence}.`;
const templates = {
  ordering_check: {
    objective: 'Confirm the account’s current ordering needs and identify whether support is useful.',
    opening: 'I wanted to check in about your current ordering needs.',
    question: 'Have your ordering needs or timing changed, and is there anything we should look into?'
  },
  category_reintroduction: {
    objective: 'Explore whether a previously ordered category is still relevant without assuming demand.',
    opening: 'I wanted to understand whether your current category needs have changed.',
    question: `Would it be useful to revisit ${Array.isArray(e.droppedCategories) && e.droppedCategories.length ? e.droppedCategories.join(', ') : 'a previously ordered category'}, or is it no longer relevant?`
  },
  service_recovery: {
    objective: 'Investigate the supplied service concern and agree an appropriate next step without making unsupported promises.',
    opening: 'I’m checking in about a possible service issue shown in the information available to us.',
    question: 'Is the issue still unresolved, and could you tell me what happened so we can investigate the right next step?'
  }
};
const t = templates[selectedActionType];
const briefingFacts = facts.length ? facts.join(' ') : 'No specific evidence values were available in the request.';
const scriptFacts = facts.length && !cautious ? ` The information provided to me shows: ${facts.join(' ')}` : '';
const script = `${t.opening}${scriptFacts} ${t.question} I will record what you tell me and make sure the appropriate team reviews any next step.`;
return [{ json: {
  ok: true,
  httpCode: 200,
  body: {
    accountId: request.accountId,
    actionType: selectedActionType,
    briefing: `${briefingFacts} ${confidenceLine}`,
    objective: t.objective,
    script,
    requiresApproval: true,
    generationMode: 'template'
  }
} }];
